[{"role": "assistant", "content": "class Calculator
  attr_reader :total_operations, :add_operations, :subtract_operations, :multiply_operations, :divide_operations, :power_operations

  def initialize
    @total_operations = 0
    @add_operations = 0
    @subtract_operations = 0
    @multiply_operations = 0
    @divide_operations = 0
    @power_operations = 0
  end

  def add(a, b)
    @total_operations += 1
    @add_operations += 1
    a + b
  end

  def subtract(a, b)
    @total_operations += 1
    @subtract_operations += 1
    a - b
  end

  def multiply(a, b)
    raise ArgumentError, "Cannot multiply complex numbers" if a.is_a?(Complex) || b.is_a?(Complex)

    @total_operations += 1
    @multiply_operations += 1
    a * b
  end

  def divide(a, b)
    raise ArgumentError, "Cannot divide complex numbers" if a.is_a?(Complex) || b.is_a?(Complex)

    @total_operations += 1
    @divide_operations += 1
    (a.to_f / b.to_f).round
  end

  def power(base, exponent)
    @total_operations += 1
    @power_operations += 1
    base ** exponent
  end

  def log(number)
    raise ArgumentError, "Input must be a positive number" if number <= 0

    Math.log(number)
  end

  def factorial(n)
    raise ArgumentError, "Input must be a non-negative integer" if n < 0

    (1..n).inject(:*) || 1
  end

  def fibonacci(n)
    raise ArgumentError, "Input must be a non-negative integer" if n < 0

    if n == 0
      return 0
    elsif n == 1
      return 1
    else
      fib = [0, 1]
      (2..n).each do |i|
        fib << fib[i - 1] + fib[i - 2]
      end
      return fib[n]
    end
  end
end"}]

