class BookNotFound < StandardError; end
class BookAlreadyBorrowed < StandardError; end

class LibraryBook

  attr_accessor :title, :author, :publication_year, :genre, :edition

  @@book_list = []

  def initialize(title, author, publication_year, genre, edition)
    @title = title
    @author = author
    @publication_year = publication_year
    @genre = genre
    @edition = edition
    @borrowed = false
    @borrower = nil
    @due_date = nil
    @reservations = []
    @history = {}
    @@book_list << self
  end

  def self.find_by_title(title)
    book = @@book_list.find { |book| book.title == title }
    raise BookNotFound, 'Book not found!' unless book
    book
  end

  def self.create(title, author, publication_year, genre, edition)
    new(title, author, publication_year, genre, edition)
  end

  def self.delete(book)
    @@book_list.delete(book)
  end

  def borrow(borrower, due_date)
    raise BookAlreadyBorrowed, 'This book is already borrowed!' if @borrowed
    @borrowed = true
    @borrower = borrower
    @due_date = due_date
    @history[Time.now] = ["Borrowed by #{borrower}", "Due date: #{due_date}"]
  end

  def return_book(borrower)
    @borrowed = false
    @borrower = nil
    @due_date = nil
    @history[Time.now] = ["Returned by #{borrower}"]
  end

  def reserve(borrower)
    @reservations << borrower
    @history[Time.now] = ["Reserved by #{borrower}"]
  end

  def cancel_reservation(borrower)
    @reservations.delete(borrower)
    @history[Time.now] = ["Cancelled reservation by #{borrower}"]
  end

  def history
    @history
  end
end
```

This class `LibraryBook` contains class methods for creating and finding books, and instance methods for borrowing, returning, reserving, and canceling reservations. It also maintains a history log of these actions.

I have also added custom exception handling for scenarios where a book is not found (`BookNotFound`) and a book is already borrowed (`BookAlreadyBorrowed`)."}]

