  attr_accessor :issue_number, :editor, :publication_date, :articles

  def initialize(issue_number, editor, publication_date)
    @issue_number = issue_number
    @editor = editor
    @publication_date = publication_date
    @articles = []
  end

  def add_article(article)
    @articles << article
  rescue => e
    puts "Error occurred while adding an article: #{e.message}"
  end

  def delete_article(article)
    @articles.delete(article)
  rescue => e
    puts "Error occurred while deleting an article: #{e.message}"
  end

  def update_article(old_article, new_article)
    index = @articles.index(old_article)
    @articles[index] = new_article if index
  rescue => e
    puts "Error occurred while updating an article: #{e.message}"
  end

  def find_article(title = nil, author = nil)
    @articles.find { |article| article.title == title || article.author == author }
  rescue => e
    puts "Error occurred while finding an article: #{e.message}"
  end
end
