[{"role": "assistant", "content": "Here is a class named `Calculator` that does everything described in the task:

```ruby
class Calculator
    attr_reader :history

    def initialize
        @history = []
    end

    def add(a, b)
        result = a + b
        @history << {operation: "add", numbers: [a, b], result: result}
        result
    end

    def subtract(a, b)
        result = a - b
        @history << {operation: "subtract", numbers: [a, b], result: result}
        result
    end

    def multiply(a, b)
        result = a * b
        @history << {operation: "multiply", numbers: [a, b], result: result}
        result
    end

    def divide(a, b)
        raise 'Cannot divide by zero!' if b == 0

        result = a / b.to_f
        @history << {operation: "divide", numbers: [a, b], result: result}
        result
    end

    def exponent(base, power)
        result = base**power
        @history << {operation: "exponent", numbers: [base, power], result: result}
        result
    end

    def square(a)
        result = a**2
        @history << {operation: "square", numbers: [a], result: result}
        result
    end

    def square_root(a)
        raise 'Cannot get square root of a negative number!' if a < 0

        result = Math.sqrt(a)
        @history << {operation: "square_root", numbers: [a], result: result}
        result
    end

    def logarithm(num, base = Math::E)
        raise 'Cannot get logarithm of a negative number or base' if num <= 0 || base <= 0

        result = Math.log(num, base)
        @history << {operation: "logarithm", numbers: [num, base], result: result}
        result
    end
end
```
